SELECT IF(x.dana = '', '', CONCAT('<br>Menimbang, bahwa #7036# juga memohon agar ahli waris tersebut ditetapkan berhak mengurus pencairan ', x.dana, ';oleh karena permohonan itu berkaitan langsung dengan kedudukan #7036# sebagai ahli waris yang telah terbukti, tidak bertentangan dengan hukum dan tidak merugikan pihak lain, maka #8554# berpendapat permohonan tersebut dapat dikabulkan;penentuan jumlah dana dan pelaksanaan pembayarannya tetap menjadi kewenangan instansi atau lembaga penyelenggara dana tersebut;')) AS data FROM (SELECT TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9700 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS dana) x